import * as fs from 'node:fs';
import * as path from 'node:path';
import * as os from 'node:os';
import * as util from 'node:util';
import * as crypto from 'node:crypto';
import * as http from 'node:http';
import * as events from 'node:events';
import * as buffer from 'node:buffer';
import * as querystring from 'node:querystring';
import * as zlib from 'node:zlib';
import * as url from 'node:url';
import * as v8 from 'node:v8';
import * as net from 'node:net';
import * as dns from 'node:dns';
import * as stream from 'node:stream';
import * as string_decoder from 'node:string_decoder';
import * as perf_hooks from 'node:perf_hooks';
import * as readline from 'node:readline';
import * as child_process from 'node:child_process';
import * as worker_threads from 'node:worker_threads';
import * as timers from 'node:timers';

export function conexoes() {
  const servidorTcp = net.createServer;
  const versaoIp = net.isIP('127.0.0.1');
  const resolver = dns.lookup;
  const resolverPromessa = dns.promises;
  const legivel = stream.Readable;
  const encanar = stream.pipeline;
  const decodificador = string_decoder.StringDecoder;
  const desempenho = perf_hooks.performance;
  const observador = perf_hooks.PerformanceObserver;
  const interface_ = readline.createInterface;
  const executar = child_process.execFileSync;
  const gerar = child_process.spawnSync;
  const principal = worker_threads.isMainThread;
  const dadosDoWorker = worker_threads.workerData;
  const agendar = timers.setTimeout;
  return {
    servidorTcp, versaoIp, resolver, resolverPromessa, legivel, encanar,
    decodificador, desempenho, observador, interface_, executar, gerar,
    principal, dadosDoWorker, agendar,
  };
}

export function inventario() {
  const raiz = path.join(os.tmpdir(), 'fixture');
  const relativo = path.relative(os.homedir(), raiz);
  const base = path.basename(raiz);
  const ext = path.extname(raiz);
  const dir = path.dirname(raiz);
  const separador = path.sep;
  const existe = fs.existsSync(raiz);
  const conteudo = existe ? fs.readFileSync(raiz, 'utf8') : '';
  const entradas = existe ? fs.readdirSync(raiz) : [];
  const estado = existe ? fs.statSync(raiz) : null;
  const constantes = fs.constants;
  const promessas = fs.promises;
  const digest = crypto.createHash('sha256').update(conteudo).digest('hex');
  const aleatorio = crypto.randomUUID();
  const bytes = crypto.randomBytes(4);
  const formatado = util.format('%s', digest);
  const inspecionado = util.inspect({ base, ext, dir, separador });
  const promisificado = util.promisify;
  const tipos = util.types;
  const plataforma = os.platform();
  const arquitetura = os.arch();
  const memoria = os.totalmem();
  const cpus = os.cpus();
  const linha = os.EOL;
  const servidor = http.createServer;
  const metodos = http.METHODS;
  const codigos = http.STATUS_CODES;
  const emissor = new events.EventEmitter();
  const maximo = events.defaultMaxListeners;
  const tampao = buffer.Buffer.from(conteudo, 'utf8');
  const limite = buffer.constants;
  const consulta = querystring.stringify({ a: '1' });
  const analisada = querystring.parse(consulta);
  const comprimido = zlib.gzipSync(tampao);
  const descomprimido = zlib.gunzipSync(comprimido);
  const endereco = url.pathToFileURL(raiz);
  const caminho = url.fileURLToPath(endereco);
  const heap = v8.getHeapStatistics();
  const serializado = v8.serialize({ ok: true });
  return {
    relativo, entradas, estado, constantes, promessas, aleatorio, bytes,
    formatado, inspecionado, promisificado, tipos, plataforma, arquitetura,
    memoria, cpus, linha, servidor, metodos, codigos, emissor, maximo,
    limite, analisada, descomprimido, caminho, heap, serializado,
  };
}

export function ambiente() {
  const porta = process.env.PORT;
  const argumentos = process.argv.slice(2);
  const versao = process.version;
  const plataforma = process.platform;
  const diretorio = process.cwd();
  const saida = process.stdout;
  const alta = process.hrtime;
  const registrar = console.log;
  const alerta = console.warn;
  const cronometro = setTimeout;
  const cancelar = clearTimeout;
  const codificador = new TextEncoder();
  const decodificador = new TextDecoder();
  const global = globalThis;
  return { porta, argumentos, versao, plataforma, diretorio, saida, alta, registrar, alerta, cronometro, cancelar, codificador, decodificador, global };
}

